import React from 'react';

const InputBar = ({ value, onChange, onSubmit, isLoading }) => {
  return (
    <form onSubmit={onSubmit} style={{ display: 'flex', padding: '10px' }}>
      <textarea
        value={value}
        onChange={onChange}
        disabled={isLoading}
        placeholder="Type your prompt here..."
        rows={2}
        style={{
          flex: 1,
          borderRadius: '8px',
          resize: 'none',
          padding: '10px',
          border: '1px solid #ccc',
          fontSize: '14px'
        }}
      />
      <button type="submit" disabled={isLoading} style={{
        marginLeft: '10px',
        borderRadius: '8px',
        backgroundColor: isLoading ? '#aaa' : '#4CAF50',
        color: 'white',
        border: 'none',
        padding: '10px 15px',
        cursor: isLoading ? 'not-allowed' : 'pointer'
      }}>
        ➤
      </button>
    </form>
  );
};

export default InputBar;
